<?php
declare(strict_types=1);
require __DIR__.'/store-common.php';
$pdo=store_setup();
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$action=(string)($_POST['action']??'');$id=(int)($_POST['id']??0);if($action==='remove'){unset($_SESSION['cart'][$id]);notice('محصول از سبد حذف شد.');}elseif($action==='update'){foreach(($_POST['qty']??[]) as $pid=>$qty){$pid=(int)$pid;$qty=max(0,min(99,(int)$qty));if($qty===0)unset($_SESSION['cart'][$pid]);else $_SESSION['cart'][$pid]=$qty;}notice('سبد خرید به‌روزرسانی شد.');}go('cart.php');}
$items=[];$total=0;
if($_SESSION['cart']){$ids=array_values(array_filter(array_map('intval',array_keys($_SESSION['cart']))));if($ids){$marks=implode(',',array_fill(0,count($ids),'?'));$s=$pdo->prepare("SELECT id,name,stock FROM products WHERE id IN ($marks)");$s->execute($ids);foreach($s->fetchAll() as $p){$qty=min((int)$_SESSION['cart'][$p['id']],(int)$p['stock']);if($qty<1){unset($_SESSION['cart'][$p['id']]);continue;}$_SESSION['cart'][$p['id']]=$qty;$p['quantity']=$qty;$items[]=$p;}}}
store_header($pdo,'سبد خرید');echo '<section class="shop-panel"><h1>سبد خرید</h1><p class="shop-muted">تمام محصولات در این نسخه رایگان‌اند؛ مبلغ پرداختی ۰ تومان است.</p>';
if(!$items)echo '<div class="shop-empty">سبد خریدت خالی است.<p><a class="shop-btn" href="./">دیدن محصولات</a></p></div>';
else {echo '<form method="post"><input type="hidden" name="_csrf" value="'.e(csrf()).'"><input type="hidden" name="action" value="update"><div style="overflow:auto"><table class="shop-table"><thead><tr><th>محصول</th><th>تعداد</th><th>مبلغ</th><th></th></tr></thead><tbody>';foreach($items as $p){echo '<tr><td><a href="product.php?id='.(int)$p['id'].'">'.e($p['name']).'</a></td><td><input aria-label="تعداد" style="width:75px;padding:8px;border:1px solid #d5e0e8;border-radius:8px" type="number" min="0" max="'.(int)$p['stock'].'" name="qty['.(int)$p['id'].']" value="'.(int)$p['quantity'].'"></td><td>۰ تومان</td><td><button class="shop-btn alt" type="submit" formaction="cart.php" formmethod="post" name="action" value="remove" onclick="this.form.insertAdjacentHTML('beforeend','<input type=hidden name=id value='+(int)$p['id']+'>')">حذف</button></td></tr>';}echo '</tbody></table></div><p style="display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap"><button class="shop-btn alt">به‌روزرسانی سبد</button><strong>جمع کل: ۰ تومان</strong></p></form><a class="shop-btn" href="checkout.php">ادامه و ثبت سفارش</a>';}
echo '</section>';store_footer();
